with cv as (select id from private.exam_prep_content_versions where content_version='p5_aw21_24_nor06_v1'), a as (select x.id,x.assessment_key from private.exam_prep_assessments x join cv on cv.id=x.content_version_id), m as (select x.content_key,x.question_id from private.exam_prep_question_content_meta x join cv on cv.id=x.content_version_id), w as (select x.id,x.task_key from private.exam_prep_written_tasks x join cv on cv.id=x.content_version_id), items(akey,ord,ckey,wkey,role,holdout) as (values
('p5_nor06_diagnostic',1,'P5NOR06-D01',null,'diagnostic',true),('p5_nor06_learning',1,'P5NOR06-L01',null,'learning',false),('p5_nor06_learning',2,'P5NOR06-L02',null,'learning',false),('p5_nor06_learning',3,'P5NOR06-L03',null,'learning',false),('p5_nor06_learning',4,null,'P5NOR06-W01','written',false),('p5_nor06_retest',1,'P5NOR06-R01',null,'retest',true),('p5_nor06_retest',2,'P5NOR06-R02',null,'retest',true),('p5_nor06_mixed',1,'P5NOR06-M01',null,'mixed',true))
insert into private.exam_prep_assessment_items(assessment_id,item_order,question_id,written_task_id,primary_skill_code,reserve_role,is_holdout)
